ALTER TABLE news_items ADD COLUMN slug TEXT NOT NULL DEFAULT '';
ALTER TABLE news_items ADD COLUMN article_body TEXT NOT NULL DEFAULT '';

UPDATE news_items
SET slug = CASE id
  WHEN 'seednews_stanford_hiit_20261005' THEN 'پژوهش-استنفورد-hiit-و-تمرین-استقامتی-20261005'
  WHEN 'seednews_lboro_nature_20261005' THEN 'دویدن-در-طبیعت-پژوهش-لافبورو-20261005'
  WHEN 'seednews_frontiers_exercise_snacks_20261006' THEN 'وقفه-کوتاه-حرکتی-آمادگی-هوازی-20261006'
  WHEN 'seednews_atlanta_dream_arena_20261006' THEN 'تیم-atlanta-dream-استیت-فارم-آرنا-20261006'
  WHEN 'seednews_irna_weightlifting_20261007' THEN 'سپاهان-صدرنشین-لیگ-وزنه-برداری-20261007'
  WHEN 'seednews_irna_womens_volleyball_20261007' THEN 'اصفهان-سه-نماینده-والیبال-زنان-20261007'
  WHEN 'seednews_mehr_womens_beach_soccer_20261007' THEN 'پرسپولیس-فوتبال-ساحلی-بانوان-20261007'
  WHEN 'seednews_mehr_para_archery_20261007' THEN 'کمپ-تمرینی-مشترک-کمانداران-پارا-20261007'
  WHEN 'seednews_mehr_womens_football_referees_20261003' THEN 'کمبود-داور-لیگ-فوتبال-زنان-20261003'
  ELSE 'خبر-' || lower(replace(substr(id, 1, 40), '_', '-'))
END,
article_body = CASE id
  WHEN 'seednews_stanford_hiit_20261005' THEN 'پژوهشگران اتحاد عملکرد انسان استنفورد پاسخ بدن به دو شیوهٔ تمرین را بررسی می‌کنند: تمرین تناوبی پرفشار (HIIT) و تمرین هوازی پیوسته با شدت متوسط. در طرح اعلام‌شده، ۹۰ بزرگسال کم‌تحرک به گروه‌های تمرین و کنترل تقسیم شدند و برنامهٔ تمرینی ۱۲ هفته، با سه جلسه در هفته، ادامه داشت.

گروه HIIT از دوره‌های کوتاه یک‌دقیقه‌ای با شدت بالا استفاده کرد و گروه دیگر ۴۰ دقیقه تمرین پیوسته با شدت متوسط انجام داد. پژوهشگران نمونه‌های خون و بافت را برای بررسی تغییرات زیستی گردآوری کردند. داده‌های اولیهٔ آمادگی قلبی‌تنفسی نشانه‌ای به نفع گروه پرفشار دارند، اما تحلیل کامل ادامه دارد؛ بنابراین این گزارش هنوز برتری قطعی یک روش را ثابت نمی‌کند.'
  WHEN 'seednews_lboro_nature_20261005' THEN 'گزارش دانشگاه لافبورو به پژوهشی دربارهٔ ورزش در محیط طبیعی می‌پردازد. یافته‌های گزارش‌شده، ورزش در فضای باز را با عملکرد بهتر در دویدن، لذت بیشتر از فعالیت و انگیزهٔ بالاتر برای ادامه مرتبط می‌دانند.

این نتایج به‌تنهایی ثابت نمی‌کنند که فضای طبیعی برای همهٔ افراد یا در هر نوع تمرینی اثر یکسان دارد. عواملی مانند تجربهٔ قبلی، مسیر، هوا و نوع فعالیت می‌توانند بر تجربهٔ ورزش اثر بگذارند؛ برای جزئیات روش و محدودیت‌های پژوهش، گزارش کامل دانشگاه و مقالهٔ علمی را ببینید.'
  WHEN 'seednews_frontiers_exercise_snacks_20261006' THEN 'یک مرور نظام‌مند و فراتحلیل، نتایج ۲۲ مطالعه را با مجموع ۹۹۴ بزرگسال کم‌تحرک بررسی کرده است. موضوع پژوهش «وقفه‌های کوتاه حرکتی» بود؛ یعنی دوره‌های کوتاه فعالیت که در طول روز جایگزین بخشی از نشستن می‌شوند.

نویسندگان برای برخی پیامدها، از جمله آمادگی هوازی و قند خون، نشانه‌هایی از بهبود گزارش کردند؛ اما دربارهٔ چربی بدن، تودهٔ عضلانی و قدرت نتیجهٔ روشنی به دست نیامد و کیفیت شواهد در چند حوزه محدود یا ناهمگون بود. این یافته‌ها امیدوارکننده‌اند، ولی نسخهٔ درمانی یا جایگزین برنامهٔ منظم ورزش محسوب نمی‌شوند.'
  WHEN 'seednews_atlanta_dream_arena_20261006' THEN 'باشگاه Atlanta Dream اعلام کرد با توافقی چندساله، از فصل ۲۰۲۷ تمام ۲۵ بازی خانگی فصل عادی خود را در سالن State Farm Arena برگزار می‌کند. این جابه‌جایی، بازی‌های خانگی تیم را به سالن بزرگ‌تری در مرکز آتلانتا می‌برد.

باشگاه افزایش تقاضای تماشاگران را از دلایل این تصمیم عنوان کرده است. تغییر سالن به‌خودی‌خود نتیجهٔ ورزشی تیم را پیش‌بینی نمی‌کند؛ اما می‌تواند ظرفیت میزبانی و دسترسی هواداران را تغییر دهد. جزئیات توافق را می‌توان در اطلاعیهٔ رسمی تیم و گزارش منبع تصویر مشاهده کرد.'
  WHEN 'seednews_irna_weightlifting_20261007' THEN 'هفتهٔ دوم لیگ برتر وزنه‌برداری مردان ایران به پایان رسید و تیم سپاهان اصفهان در صدر جدول قرار گرفت. این خبر، وضعیت جدول را پس از پایان هفتهٔ دوم گزارش می‌کند.

صدرنشینی در این مقطع به معنای قهرمانی نهایی نیست؛ رقابت لیگ ادامه دارد و جایگاه تیم‌ها می‌تواند در هفته‌های بعد تغییر کند. برای ریز نتایج و عملکرد هر تیم، گزارش کامل ایرنا را بخوانید.'
  WHEN 'seednews_irna_womens_volleyball_20261007' THEN 'قرعه‌کشی فصل تازهٔ لیگ برتر والیبال زنان ایران با حضور ۱۴ تیم انجام شد. بر اساس گزارش ایرنا، ذوب‌آهن، سپاهان و پدیده صنعت اوج گلپایگان سه نمایندهٔ استان اصفهان هستند که در گروه دوم قرار گرفته‌اند.

حضور سه تیم از یک استان، رقابت‌های گروه دوم را برای هواداران اصفهانی پررنگ‌تر می‌کند؛ با این حال، نتیجهٔ مسابقات به عملکرد تیم‌ها در طول فصل بستگی دارد. برنامهٔ کامل رقابت‌ها و جزئیات قرعه‌کشی در گزارش اصلی ایرنا آمده است.'
  WHEN 'seednews_mehr_womens_beach_soccer_20261007' THEN 'باشگاه پرسپولیس برای نخستین‌بار در رقابت‌های فوتبال ساحلی بانوان تیم‌داری می‌کند. طبق گزارش خبرگزاری مهر، این باشگاه امتیاز یک تیم را خریداری کرده تا وارد لیگ برتر فوتبال ساحلی بانوان تهران شود.

گزارش اولیه از برگزاری مسابقات در روزهای ۲۴ و ۲۵ مهر با حضور پنج تیم خبر می‌دهد. حضور نام یک باشگاه پرهوادار می‌تواند توجه بیشتری به این رقابت‌ها جلب کند، اما کیفیت و نتیجهٔ تیم پس از شروع مسابقات مشخص خواهد شد. خبرگزاری مهر منبع اصلی این خبر است.'
  WHEN 'seednews_mehr_para_archery_20261007' THEN 'در جریان بازدید از اردوی پاراتیراندازی با کمان و پاراشنا، وزیر ورزش دستور داد ورزشکاران پارا نیز هم‌زمان با کمانداران از امکانات یک کمپ تمرینی استفاده کنند. گزارش خبرگزاری مهر همچنین به فراهم‌کردن تجهیزات پایهٔ سیبل برای تمرین اشاره دارد.

دسترسی مشترک به امکانات تمرینی می‌تواند هماهنگی و بهره‌برداری از مجموعه را آسان‌تر کند؛ اما فراهم‌بودن تجهیزات مناسب و سازگاری محیط با نیازهای ورزشکاران پارا برای استفادهٔ ایمن و مؤثر ضروری است. جزئیات بیشتر در گزارش اصلی مهر آمده است.'
  WHEN 'seednews_mehr_womens_football_referees_20261003' THEN 'گزارش خبرگزاری مهر در ۱۱ مهر از احتمال وقفه‌ای یک‌هفته‌ای در لیگ برتر فوتبال زنان به‌دلیل کمبود داور خبر داد. در همان زمان، طبق گزارش، برای پنجرهٔ فیفادی ۱۳ تا ۲۱ مهر نیز دیدار رسمی‌ای برای تیم ملی زنان ایران اعلام نشده بود.

این خبر وضعیت و پیش‌بینی‌های زمان انتشار در ۱۱ مهر را بازتاب می‌دهد و نباید آن را به‌عنوان برنامهٔ قطعی امروز لیگ یا تیم ملی خواند. برای اطلاع از تغییرات بعدی تقویم، خبرهای جدیدتر و اطلاعیه‌های رسمی را دنبال کنید.'
  ELSE COALESCE(NULLIF(article_body, ''), summary)
END
WHERE slug = '' OR slug IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_news_items_slug ON news_items(slug);
